    add("sample","670",entry("重晶石不要写成碳酸盐","两组近直交解理、一级黄橙和正中突起是组合证据；闪突起加菱面解理才是方解石。",["ref-53"],"实验教学目标与实验课程内容"));
    add("sample","713",entry("蓝色多色性要分单偏光","蓝闪石的蓝紫色在单偏光下转台变化；正交下的蓝色可能是干涉色或钠质辉石的异常色，先看轴性和解理角。",["ref-78"],"Identification; Similar minerals"));
    add("sample","736",entry("空晶石十字不是十字石","红柱石横切面近方形，碳质包裹体可排成十字；延性为负，与矽线石的正延性分开。",["ref-75"],"Important properties; Similar minerals"));
    add("sample","740",entry("楔形高级白先排除方解石","榍石晶形常呈楔形或菱形，正极高突起、高级白；方解石有闪突起和菱面解理。",["ref-73"],"Identification; Important properties"));
    add("sample","855",entry("针状正延性对红柱石","矽线石呈针状或纤维状，一组解理，正延性、干涉色可到二级；红柱石负延性、一级黄。",["ref-70"],"Appearance and habit; Similar minerals"));
    add("sample","856",entry("堇青石的虫蛀与连晶","新鲜颗粒可像石英一样一级灰白；三连晶或六连晶、锆石晕圈和边缘蚀变（虫蛀）用来与石英分开。",["ref-71"],"Identification; Similar minerals"));
    add("sample","858",entry("异常蓝不是绿泥石专利","黝帘石正高突起、一级灰，含铁锰时可出现异常干涉色；绿泥石突起低、片状解理。",["ref-51"],"Identification"));
    add("sample","866",entry("电气石吸收与黑云母相反","柱体延长垂直下偏光时吸收最强；黑云母则是解理平行下偏光时最深。横切面看弧面三角形。",["ref-45"],"Similar minerals"));
    add("sample","867",entry("斜消光把蓝晶石从红柱石里捞出来","蓝晶石板状高突起，消光相对解理可达约 30°；红柱石平行消光，矽线石针状正延性。",["ref-79"],"Extinction angle; Important properties"));
    add("sample","868",entry("符山石低双折射加异常色","正高突起、一级灰并常有斑点状异常色，横切面近方形；不要按石榴子石的均质全消光来报。",["ref-43"],"Identification; isotropic appearance"));
    add("sample","869",entry("穿插十字要看金黄突起","十字石常呈金黄至蜜黄色、正高突起；红柱石空晶石的碳质十字在无色柱体里，二者不是同一种。",["ref-86"],"staurolite thin-section occurrence"));
    add("sample","870",entry("硬绿泥石看砂钟和负延性","板状或束状，正高突起、一级灰，常见砂钟构造；负延性，不要只凭绿色写成绿泥石。",["ref-80"],"Garnet and Chloritoid 照片说明：high relief, twinning, first order"));
    add("sample","871",entry("霞石表面脏、一轴负","断面常呈四边或六边，负低至正低突起，一级灰，表面常不洁净；与石英的一轴正、表面干净相反。",["ref-82"],"Tectosilicates 段与似长石产状"));
    add("sample","874",entry("硅灰石解理夹角不是 56°","多组解理夹角大于 60°，干涉色多停在一级；透闪石是角闪石式 56°/124°，干涉色可到二级。",["ref-81"],"wollastonite identification / cleavage contrast with amphibole"));
    add("sample","875",entry("绿辉石先认榴辉岩组合","淡绿色辉石、辉石式解理，典型限于榴辉岩；不要只凭绿色写成普通辉石。",["ref-72"],"Occurrence; Omphacite typically restricted to eclogites"));
    add("sample","876",entry("透闪石横切面看 60°/120°","无色至淡绿的角闪石，纵切一组解理、横切两组约 60°/120°；直闪石才是平行消光。",["ref-76"],"Cleavage; Similar Minerals"));
    add("sample","877",entry("刚玉的近直交缝是裂理","无真正解理，近直交者为裂理或裂开；不要写成完全解理。",["ref-82"],"Oxides & accessory minerals"));
    add("sample","878",entry("尖晶石均质而且常有颜色","等轴、高突起、无解理、正交全消光；常见绿、褐等吸收色，石榴子石多近无色。",["ref-74"],"Important properties; Similar minerals"));
    add("sample","879",entry("霓辉石负延性加绿色多色性","碱性辉石绿色多色性明显、负延性；普通辉石、透辉石多为正延性、多色性弱。",["ref-72"],"Color; Identification"));
    add("sample","881",entry("霓石干涉色高、消光近平行","正极高突起，干涉色可到三级并常被体色掩盖，近平行消光、负延性；δ 高不是方解石那种闪突起。",["ref-72"],"Acmite may exhibit third order interference colors"));
    add("sample","885",entry("钙沸石斜消光负延性","负极低突起、一级灰白，斜消光、负延性；杆沸石、钠沸石多为平行消光正延性。",["ref-53"],"实验课程内容：消光与延性测定"));
    add("sample","887",entry("石膏负突起对硬石膏","负低突起、最高一级淡黄，常见燕尾双晶；硬石膏正突起、干涉色可到三级。",["ref-53"],"实验课程内容：突起与干涉色"));
    add("sample","888",entry("硬石膏三组直交解理","正低至正中突起，三组近直交解理切成矩形，干涉色远高于石膏。",["ref-53"],"实验课程内容：解理角与干涉色"));
    add("sample","889",entry("滑石干涉色高但硬度低","片状正低突起，干涉色可高到像白云母；常与透闪石共生于大理岩或超基性岩蚀变。",["ref-77"],"Talc with Tremolite 照片说明"));
    add("sample","890",entry("方钠石均质全消光","负低突起、正交始终黑暗；白榴石常有包裹体和聚片双晶，方钠石一般没有。",["ref-55"],"Examination of Isotropic Substances"));
    add("sample","891",entry("绿柱石负延性对石英","六方柱、一级灰白，负延性、负光性；石英正延性、一轴正。",["ref-39"],"Similar minerals; beryl vs quartz"));
    add("sample","896",entry("辉绿玢岩先认斑状再认辉绿结构","斑晶与基质分开观察：基质仍可保留斜长石格架、辉石充填；粒度细不等于换成喷出岩名。",["ref-56"],"章节正文及岩类对照表"));
    add("sample","897",entry("辉绿岩看结构不看颜色","斜长石板条搭格、辉石充填是辉绿结构；辉长岩更粗，玄武岩基质更玻基、微晶更细。",["ref-56"],"章节正文及岩类对照表"));
    add("sample","900",entry("闪长岩是中性深成岩","斜长石加角闪石为主，石英很少；不要因为有角闪石就写成角闪岩。",["ref-56"],"章节正文及岩类对照表"));
    add("sample","901",entry("石英闪长岩石英仍是配角","石英多于闪长岩、仍少于花岗闪长岩；斜长石环带还在，不要改叫花岗岩。",["ref-56"],"章节正文及岩类对照表"));
    add("sample","902",entry("粗面岩是正长岩的喷出对应","长石微晶定向排队，石英很少；流纹岩才常见石英斑晶和球粒。",["ref-56"],"章节正文及岩类对照表"));
    add("sample","906",entry("花岗细晶岩是细粒长英质脉","矿物仍是石英加长石，只是粒很细；细粒不等于基性。",["ref-56"],"章节正文及岩类对照表"));

    add("rock","dunite",entry("纯橄榄岩认裂纹不认解理","几乎全是橄榄石：高突起、不规则裂纹、可沿裂隙蛇纹石化；辉石岩才有近直交的平直解理。",["ref-44","ref-56"],"Olivine: lack of cleavage / alteration; 岩类对照表"));
    add("rock","kimberlite",entry("金伯利岩斑晶浑圆加角砾","斑晶常浑圆、基质蚀变强，可含石榴子石；不要只凭斑状写成玢岩。",["ref-56","ref-43"],"岩类对照表；Garnet occurrence"));
    add("rock","amphibolite",entry("角闪岩看 56°/124°","绿色多色性加角闪石式解理；辉石岩解理近直交、多色性弱。",["ref-42"],"hornblende cleavage and pleochroism"));
    add("rock","pyroxenite",entry("辉石岩解理近直交","横切面 87°/93° 平直解理，干涉色通常低于橄榄石；橄榄石是裂纹不是解理。",["ref-41","ref-44"],"cpx cleavage; olivine fracture"));
    add("rock","diabase",entry("辉绿岩是细粒辉长质","矿物组合近辉长岩，结构是斜长石格架、辉石充填；玄武岩基质更玻基。",["ref-56"],"章节正文及岩类对照表"));
    add("rock","anorthosite",entry("斜长岩几乎全是斜长石","聚片双晶的长石占绝对多数；大理岩才有闪突起和菱面解理。",["ref-49","ref-40"],"plagioclase twinning; calcite twinkling"));
    add("rock","granodio",entry("花岗闪长岩斜长石多于钾长石","石英比花岗岩少、钾长石更少，环带斜长石常见；不要只凭浅色写成花岗岩。",["ref-56"],"章节正文及岩类对照表"));
    add("rock","pxdiorite",entry("辉石闪长岩仍是中性岩","斜长石加角闪石的闪长岩组合里出现辉石；辉长岩的斜长石更基性、辉石更多。",["ref-56","ref-41"],"岩类对照表；cpx identification"));
    add("rock","porphyrite",entry("闪长玢岩是斑状闪长岩","环带斜长石当斑晶，基质仍是闪长质；安山岩基质有更多微晶和玻璃。",["ref-56"],"章节正文及岩类对照表"));
    add("rock","syenite",entry("正长岩石英很少","碱性长石大板、卡式双晶常见；出现较多石英就进入花岗岩一侧。",["ref-56","ref-48"],"岩类对照表；K-spar identification"));
    add("rock","trachyte",entry("粗面岩长石微晶定向","喷出对应正长岩，石英很少；流纹岩才常见石英斑晶和球粒。",["ref-56"],"章节正文及岩类对照表"));
    add("rock","lampro",entry("煌斑岩暗色矿物当斑晶","黑云母或角闪石斑晶粗大，基质细；片岩的云母是变质面理，不是斑状岩浆结构。",["ref-45","ref-58"],"biotite habit; 变质岩分类"));
    add("rock","greisen",entry("云英岩是花岗岩的蚀变","石英加白云母，可含电气石；原岩结构被交代削弱，不要当成普通片岩。",["ref-47","ref-59"],"muscovite; contact metamorphism and hydrothermal"));
    add("rock","propylite",entry("青磐岩满眼绿加异常蓝","绿帘石、绿泥石、阳起石组合，可见异常干涉色；矽卡岩才常见石榴子石全消光。",["ref-51","ref-50"],"epidote; chlorite anomalous colors"));
