  var cards = [{"id":"struct3d_pd_horst_01","subject":"struct","cat":"地质图画法","name":"USGS 块体图：地垒与地堑","en":"USGS horst and graben block","group":"地质图画法","points":"相向正断层夹持的下降盘是地堑，两侧上升盘是地垒。上盘相对下降。对照三维台「地堑地垒」。","geo":"","ref":"U.S. Geological Survey","imgs":[{"k":"img/ext/struct3d/pd_horst_graben.jpg","cap":"USGS 地垒—地堑块体图（公有领域）","w":271,"h":135}],"src":{"t":"USGS 地垒—地堑块体图（公有领域）","u":"https://earthquake.usgs.gov/learn/glossary/?term=graben","l":"Public domain","a":"U.S. Geological Survey"}},{"id":"struct3d_pd_folds_01","subject":"struct","cat":"地质图画法","name":"USGS 块体图：褶皱与断层","en":"USGS folds and faults block","group":"地质图画法","points":"一张图对照背斜、向斜、正断层、逆断层、逆冲和走滑。先分清上盘运动方向，再读平面错开。","geo":"","ref":"U.S. Geological Survey","imgs":[{"k":"img/ext/struct3d/pd_faults_folds.jpg","cap":"USGS 褶皱与断层示意块体（公有领域）","w":360,"h":458}],"src":{"t":"USGS 褶皱与断层示意块体（公有领域）","u":"https://3dparks.wr.usgs.gov/nyc/highlands/highlands.html","l":"Public domain","a":"U.S. Geological Survey"}},{"id":"struct3d_pd_geotime_01","subject":"struct","cat":"地质图画法","name":"USGS 地层块体：科罗拉多高原阶梯","en":"USGS Colorado Plateau stratigraphic block","group":"地质图画法","points":"大峡谷—锡安—布莱斯的地层台阶：同一套近水平层被侵蚀切出台阶，顶面是地形，正面是地层柱。水平层界线随等高。","geo":"","ref":"U.S. Geological Survey","imgs":[{"k":"img/ext/struct3d/pd_geotime.gif","cap":"USGS 地质年代表插图：科罗拉多高原地层块体（公有领域）","w":800,"h":572}],"src":{"t":"USGS 地质年代表插图：科罗拉多高原地层块体（公有领域）","u":"https://pubs.usgs.gov/gip/geotime/section.html","l":"Public domain","a":"U.S. Geological Survey"}},{"id":"struct3d_pd_teton_01","subject":"struct","cat":"地质图画法","name":"NPS 块体图：提顿正断层山","en":"NPS Teton normal-fault block","group":"地质图画法","points":"提顿山脉是下盘上升的断块山，杰克逊霍尔是上盘下降的谷地。高角度正断层，断层崖面向盆地。","geo":"","ref":"U.S. National Park Service","imgs":[{"k":"img/ext/struct3d/pd_teton.jpg","cap":"美国国家公园管理局：提顿断层块体（公有领域）","w":400,"h":254}],"src":{"t":"美国国家公园管理局：提顿断层块体（公有领域）","u":"https://www.nps.gov/grte/learn/nature/geologicformations.htm","l":"Public domain","a":"U.S. National Park Service"}},{"id":"struct3d_pd_stair_01","subject":"struct","cat":"地质图画法","name":"NPS 地形块体：大阶梯","en":"NPS Grand Staircase topographic block","group":"地质图画法","points":"大峡谷到布莱斯的彩色悬崖阶梯：近水平沉积层被逐级剥蚀，地形台阶对应地层界线。用来读水平岩层的顶面与侧面。","geo":"","ref":"U.S. National Park Service","imgs":[{"k":"img/ext/struct3d/pd_staircase.jpg","cap":"NPS 大阶梯三维地质—地形块体（公有领域，已缩小）","w":1800,"h":549}],"src":{"t":"NPS 大阶梯三维地质—地形块体（公有领域，已缩小）","u":"https://www.nps.gov/brca/learn/nature/grandstaircase.htm","l":"Public domain","a":"U.S. National Park Service"}},{"id":"struct3d_pd_wedge_01","subject":"struct","cat":"地质图画法","name":"USGS 块体图：增生楔","en":"USGS accretionary wedge cutaway","group":"地质图画法","points":"洋壳俯冲时，海沟处刮下来的沉积堆成增生楔，后方是火山弧。用来对照俯冲带的三维位置，不是逆冲推覆的陆内样式。","geo":"","ref":"U.S. Geological Survey","imgs":[{"k":"img/ext/struct3d/pd_accretion.gif","cap":"USGS 术语图：增生楔（公有领域）","w":378,"h":294}],"src":{"t":"USGS 术语图：增生楔（公有领域）","u":"https://earthquake.usgs.gov/learn/glossary/?term=accretionary%20wedge","l":"Public domain","a":"U.S. Geological Survey"}},{"id":"struct3d_pd_oceancont_01","subject":"struct","cat":"地质图画法","name":"USGS 块体图：洋陆汇聚","en":"USGS ocean-continent convergent margin","group":"地质图画法","points":"This Dynamic Earth 图 21：洋壳俯冲到大陆之下，海沟、贝尼奥夫带、陆缘火山弧。与增生楔图一起看俯冲带解剖。","geo":"","ref":"U.S. Geological Survey · Kious & Tilling","imgs":[{"k":"img/ext/struct3d/pd_oceancont.gif","cap":"USGS《This Dynamic Earth》洋陆汇聚块体（公有领域）","w":302,"h":178}],"src":{"t":"USGS《This Dynamic Earth》洋陆汇聚块体（公有领域）","u":"https://pubs.usgs.gov/gip/dynamic/understanding.html","l":"Public domain","a":"U.S. Geological Survey · Kious & Tilling"}},{"id":"struct3d_pd_mars_01","subject":"struct","cat":"地质图画法","name":"NASA 地形图：火星 MOLA 高程","en":"NASA MOLA Mars topographic globes","group":"地质图画法","points":"火星全球高程：暖色为高地与火山隆起（塔尔西斯），冷色为低盆地（海拉斯）。颜色是海拔，不是岩性。用来练习读地形起伏，不是地壳剖面。","geo":"","ref":"NASA / JPL / MOLA team","imgs":[{"k":"img/ext/struct3d/pd_mars_topo.jpg","cap":"NASA/JPL PIA02820 火星 MOLA 高程球（公有领域）","w":693,"h":480}],"src":{"t":"NASA/JPL PIA02820 火星 MOLA 高程球（公有领域）","u":"https://photojournal.jpl.nasa.gov/catalog/PIA02820","l":"Public domain","a":"NASA / JPL / MOLA team"}}];
